import { t } from '../i18n';
import { MotionDetails } from '../motion/Presence';
import { useLayoutEffect, useRef, useState } from 'react';
import { PrecisionRange } from './PrecisionRange';
import { ParameterGlyph, parameterGlyphFor, type ParameterGlyphName } from './ParameterGlyph';

/** Reveal only the active control inside its existing scroll surface, never the page. */
export function parameterControlScrollTop({
  scrollTop,
  viewportTop,
  viewportHeight,
  controlTop,
  controlHeight,
}: {
  scrollTop: number;
  viewportTop: number;
  viewportHeight: number;
  controlTop: number;
  controlHeight: number;
}): number {
  const margin = 6;
  if (controlTop < viewportTop + margin || controlHeight > viewportHeight - margin * 2)
    return Math.max(0, scrollTop + controlTop - viewportTop - margin);
  const overflow = controlTop + controlHeight - (viewportTop + viewportHeight - margin);
  return overflow > 0 ? scrollTop + overflow : scrollTop;
}

export type ShelfControl = {
  id: string;
  label: string;
  value: number;
  min: number;
  max: number;
  step: number;
  neutral?: number;
  unit?: string;
  gradient?: string;
  description?: string;
  disabled?: boolean;
  onChange: (value: number) => void;
  onReset?: () => void;
  integer?: boolean;
  glyph?: ParameterGlyphName;
  shortLabel?: string;
  /** Brush configuration is not an applied image adjustment. */
  kind?: 'adjustment' | 'setting';
};

export function isShelfControlAdjusted(control: ShelfControl): boolean {
  return control.kind !== 'setting' && control.neutral !== undefined &&
    Math.abs(control.value - control.neutral) > 1e-8;
}
/** One precise active control; adjacent tools stay discoverable without a wall of sliders. */
export function ParameterShelf({
  controls,
  label,
  onCommit,
  onCancel,
}: {
  controls: ShelfControl[];
  label: string;
  onCommit?: (label: string) => void;
  onCancel?: () => void;
}) {
  const [selectedId, setSelectedId] = useState(
    controls.find((control) => !control.disabled)?.id ?? controls[0]?.id ?? '',
  );
  const shelf = useRef<HTMLElement>(null);
  const current = useRef<HTMLDivElement>(null);
  const choices = useRef<HTMLDivElement>(null);
  const revealRequested = useRef(false);
  const active =
    controls.find((control) => control.id === selectedId && !control.disabled) ??
    controls.find((control) => !control.disabled) ??
    controls[0];
  function revealCurrent() {
    revealRequested.current = false;
    const element = shelf.current;
    if (
      !element ||
      getComputedStyle(element).getPropertyValue('--parameter-shelf-compact').trim() !== '1'
    )
      return;
    const scroller = element.closest<HTMLElement>('.inspector-scroll');
    const control = current.current?.querySelector<HTMLElement>('.precision-control');
    if (!scroller || !control || scroller.clientHeight === 0) return;
    const viewport = scroller.getBoundingClientRect();
    const target = control.getBoundingClientRect();
    scroller.scrollTop = parameterControlScrollTop({
      scrollTop: scroller.scrollTop,
      viewportTop: viewport.top + scroller.clientTop,
      viewportHeight: scroller.clientHeight,
      controlTop: target.top,
      controlHeight: target.height,
    });
  }
  useLayoutEffect(() => {
    if (revealRequested.current) revealCurrent();
    const rail = choices.current;
    const selected = rail?.querySelector<HTMLElement>('[aria-pressed="true"]');
    if (!rail || !selected || rail.scrollWidth <= rail.clientWidth) return;
    const visible = rail.getBoundingClientRect();
    const item = selected.getBoundingClientRect();
    if (item.left < visible.left) rail.scrollLeft += item.left - visible.left - 4;
    else if (item.right > visible.right) rail.scrollLeft += item.right - visible.right + 4;
  }, [active?.id]);
  if (!active) return <p className="control-note">{t('当前范围没有可调整的参数。')}</p>;
  function selectControl(id: string) {
    if (active && active.id !== id) onCommit?.(active.label);
    revealRequested.current = true;
    setSelectedId(id);
    if (active?.id === id) revealCurrent();
  }
  return (
    <section ref={shelf} className="parameter-shelf parameter-shelf-r5" aria-label={t(label)}>
      <div ref={current} className="parameter-shelf-current" data-motion="parameter-current">
        <PrecisionRange
          key={active.id}
          label={t(active.label)}
          value={active.value}
          min={active.min}
          max={active.max}
          step={active.step}
          neutral={active.neutral}
          adjusted={isShelfControlAdjusted(active)}
          unit={active.unit === 'ratio' ? '' : t(active.unit ?? '')}
          gradient={active.gradient}
          disabled={active.disabled}
          integer={active.integer}
          onChange={active.onChange}
          onCommit={() => onCommit?.(active.label)}
          onCancel={onCancel}
          onReset={active.onReset}
        />
      </div>
      <div
        ref={choices}
        className="parameter-shelf-options"
        role="group"
        aria-label={t('{name}选项', { name: t(label) })}
        data-motion="parameter-options"
        onKeyDown={(event) => {
          if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
          const buttons = [
            ...event.currentTarget.querySelectorAll<HTMLButtonElement>('button:not(:disabled)'),
          ];
          const index = buttons.indexOf(event.target as HTMLButtonElement);
          if (index < 0) return;
          event.preventDefault();
          const next =
            event.key === 'Home'
              ? 0
              : event.key === 'End'
                ? buttons.length - 1
                : (index + (event.key === 'ArrowLeft' ? -1 : 1) + buttons.length) % buttons.length;
          const target = buttons[next];
          if (!target) return;
          target.focus({ preventScroll: true });
          const rail = event.currentTarget;
          const viewport = rail.getBoundingClientRect();
          const item = target.getBoundingClientRect();
          const left = viewport.left + rail.clientLeft;
          const top = viewport.top + rail.clientTop;
          if (item.left < left) rail.scrollLeft += item.left - left;
          else if (item.right > left + rail.clientWidth)
            rail.scrollLeft += item.right - left - rail.clientWidth;
          if (item.top < top) rail.scrollTop += item.top - top;
          else if (item.bottom > top + rail.clientHeight)
            rail.scrollTop += item.bottom - top - rail.clientHeight;
        }}
      >
        {controls.map((control) => (
          <button
            type="button"
            key={control.id}
            aria-pressed={active.id === control.id}
            disabled={control.disabled}
            tabIndex={active.id === control.id ? 0 : -1}
            aria-label={t('{v0}，{v1}{v2}{v3}', {
              v0: t(control.label),
              v1: Number(control.value.toFixed(4)),
              v2: control.unit === 'ratio' ? '' : t(control.unit ?? ''),
              v3: isShelfControlAdjusted(control) ? t('，已调整') : '',
            })}
            data-adjusted={isShelfControlAdjusted(control) ? 'true' : undefined}
            title={control.disabled && control.description ? t(control.description) : undefined}
            onClick={() => selectControl(control.id)}
          >
            <span className="parameter-choice-symbol" aria-hidden="true">
              <ParameterGlyph name={control.glyph ?? parameterGlyphFor(control.id)} />
            </span>
            <span className="parameter-choice-label">{t(control.shortLabel ?? control.label)}</span>
            <small>
              {Number(control.value.toFixed(4))}
              {control.unit === 'ratio' ? '' : t(control.unit ?? '')}
            </small>
            {isShelfControlAdjusted(control) && <i aria-hidden="true" />}
          </button>
        ))}
      </div>
      {active.description && (
        <MotionDetails key={active.id + '-description'} className="parameter-description">
          <summary title={t('{name}说明', { name: t(active.label) })}>
            <svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" strokeWidth="1.6" aria-hidden="true"><circle cx="12" cy="12" r="9" /><path d="M12 11v6M12 7h.01" strokeLinecap="round" /></svg>
            <span className="sr-only">{t('{name}说明', { name: t(active.label) })}</span>
          </summary>
          <p className="control-note">{t(active.description)}</p>
        </MotionDetails>
      )}
    </section>
  );
}

import { editorControlText } from './editor-control-copy';
import { useMemo, useState } from 'react';
import { ArrowClockwise, ArrowCounterClockwise, CaretDown } from '@phosphor-icons/react';
import { formatNumber, t } from '../i18n';
import { recipeDifferences } from '../ai/recipeDiff';
import { interactionText } from '../workspace/interaction-copy';
import { historyDetails } from './history-details';
import { historyText } from './history-copy';
import type { EditorState } from './useEditor';

function formatValue(
  value: string | number | boolean,
  unit = '',
  userText = false,
  presence = false,
) {
  if (typeof value === 'boolean')
    return presence ? historyText(value ? '存在' : '无') : interactionText(value ? 'on' : 'off');
  return typeof value === 'number'
    ? `${formatNumber(value, { maximumFractionDigits: 4 })}${unit}`
    : userText
      ? value
      : historyText(value);
}

export function HistoryPanel({ editor }: { editor: EditorState }) {
  const [expanded, setExpanded] = useState<number | null>(null);
  const summaries = useMemo(
    () =>
      editor.history.map((item, index) =>
        index ? recipeDifferences(editor.history[index - 1]!.recipe, item.recipe) : [],
      ),
    [editor.history],
  );
  const detailed = useMemo(
    () =>
      expanded !== null && expanded > 0 && editor.history[expanded]
        ? historyDetails(editor.history[expanded - 1]!.recipe, editor.history[expanded]!.recipe)
        : [],
    [editor.history, expanded],
  );
  const previewChanges = useMemo(() => {
    const committed = editor.history[editor.historyIndex]?.recipe;
    return editor.hasUncommittedPreview && committed ? recipeDifferences(committed, editor.recipe) : [];
  }, [editor.hasUncommittedPreview, editor.history, editor.historyIndex, editor.recipe]);
  return (
    <section className="advanced-tool-family" data-motion="advanced-history">
      <div className="advanced-row history-actions">
        <button className="text-button" disabled={!editor.canUndo} onClick={editor.undo}>
          <ArrowCounterClockwise size={17} />
          {t('撤销本次编辑')}
        </button>
        <button className="text-button" disabled={!editor.canRedo} onClick={editor.redo}>
          <ArrowClockwise size={17} />
          {t('重做本次编辑')}
        </button>
      </div>
      <ol className="advanced-history-list detailed-history-list">
        {editor.hasUncommittedPreview && (
          <li className="history-preview-entry" data-preview="true">
            <strong>{editorControlText('当前预览')}</strong>
            {previewChanges.length > 0 && <p>{previewChanges.slice(0, 4).map((change) =>
              `${t(change.label)} ${formatValue(change.before, change.unit)} → ${formatValue(change.after, change.unit)}`,
            ).join(' · ')}</p>}
            <div className="history-preview-actions">
              <button type="button" className="text-button" onClick={editor.cancelPreview}>
                <ArrowCounterClockwise size={16} />{editorControlText('撤销预览')}
              </button>
            </div>
          </li>
        )}
        {editor.history.map((item, index) => {
          const changes = summaries[index] ?? [];
          return (
            <li key={index} data-selected={index === editor.historyIndex && !editor.hasUncommittedPreview}>
              <div className="history-entry-row">
                <button
                  className="history-restore"
                  onClick={() => editor.commit(item.recipe, t('从本地记录恢复：') + item.label)}
                  disabled={index === editor.historyIndex && !editor.hasUncommittedPreview}
                >
                  <span className="history-index">{String(index + 1).padStart(2, '0')}</span>
                  <span className="history-entry-copy">
                    <strong>{t(item.label)}</strong>
                    {changes.length > 0 && (
                      <small>
                        {changes
                          .slice(0, 2)
                          .map(
                            (change) =>
                              `${t(change.label)} ${formatValue(change.before, change.unit)} → ${formatValue(change.after, change.unit)}`,
                          )
                          .join(' · ')}
                      </small>
                    )}
                    {index === 0 && t(item.label) !== interactionText('originalState') && (
                      <small>{interactionText('originalState')}</small>
                    )}
                  </span>
                  {index === editor.historyIndex && !editor.hasUncommittedPreview && (
                    <small className="history-current">{t('当前')}</small>
                  )}
                </button>
                {index > 0 && (
                  <button
                    type="button"
                    className="history-expand"
                    aria-expanded={expanded === index}
                    aria-label={interactionText('historyDetails') + ' · ' + t(item.label)}
                    onClick={() => setExpanded(expanded === index ? null : index)}
                  >
                    <CaretDown size={15} />
                  </button>
                )}
              </div>
              {expanded === index && (
                <dl className="history-change-details">
                  {detailed.length ? (
                    detailed.map((detail, i) => (
                      <div key={i}>
                        <dt>
                          <span>
                            {detail.scopeIsUserName ? detail.scope : historyText(detail.scope)}
                          </span>
                          {historyText(detail.label)}
                        </dt>
                        <dd>
                          <span>
                            {formatValue(
                              detail.before,
                              detail.unit,
                              detail.valuesAreUserText,
                              detail.presence,
                            )}
                          </span>
                          <i aria-hidden>→</i>
                          <strong>
                            {formatValue(
                              detail.after,
                              detail.unit,
                              detail.valuesAreUserText,
                              detail.presence,
                            )}
                          </strong>
                        </dd>
                      </div>
                    ))
                  ) : (
                    <div>
                      <dt className="sr-only">{interactionText('historyDetails')}</dt>
                      <dd>{interactionText('noParameterChanges')}</dd>
                    </div>
                  )}
                </dl>
              )}
            </li>
          );
        })}
      </ol>
    </section>
  );
}

/* Editor-only presentation. Parameter geometry and gesture transactions remain native. */
.parameter-shelf.parameter-shelf-r5 {
  --parameter-shelf-compact: 1;
  position: relative;
  gap: 8px;
  min-width: 0;
}
.parameter-shelf.parameter-shelf-r5 > .parameter-shelf-current {
  position: static;
  order: 0;
  padding: 0 2px;
  background: transparent;
}
.parameter-shelf.parameter-shelf-r5 .precision-heading {
  padding-inline-end: 34px;
  min-height: 42px;
}
.parameter-shelf.parameter-shelf-r5 .precision-heading > label {
  visibility: visible;
  min-width: 0;
  font-size: 13px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}
.parameter-shelf.parameter-shelf-r5 .precision-readout .precision-value {
  background: transparent;
  min-width: 52px;
  min-height: 42px;
  font-size: 20px;
  letter-spacing: -.045em;
}
.parameter-shelf.parameter-shelf-r5 .precision-readout .precision-value small {
  font-size: 10px;
  margin-inline-start: 3px;
  letter-spacing: 0;
}
.parameter-shelf.parameter-shelf-r5 .precision-readout .precision-reset {
  min-width: 32px;
  min-height: 42px;
}
.parameter-shelf.parameter-shelf-r5 .precision-track,
.parameter-shelf.parameter-shelf-r5 .precision-track input[type='range'] {
  min-height: 44px;
  height: 44px;
}
.parameter-shelf.parameter-shelf-r5 .precision-track input[type='range']::-webkit-slider-thumb {
  width: 22px;
  height: 22px;
  margin-top: -8.5px;
  border: 3px solid var(--surface);
  box-shadow: 0 0 0 2px var(--accent), 0 2px 6px rgb(var(--color-shadow) / 10%);
}
.parameter-shelf.parameter-shelf-r5 .precision-track input[type='range']::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border: 3px solid var(--surface);
  box-shadow: 0 0 0 2px var(--accent), 0 2px 6px rgb(var(--color-shadow) / 10%);
}
.parameter-shelf.parameter-shelf-r5 .precision-neutral { top: 16px; }
.parameter-shelf.parameter-shelf-r5 > .parameter-shelf-options {
  display: flex;
  flex-wrap: nowrap;
  align-items: stretch;
  gap: 6px;
  padding: 4px 2px 7px;
  min-height: 90px;
  max-height: none;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-padding-inline: 4px;
  scroll-snap-type: x proximity;
  scrollbar-width: thin;
  overscroll-behavior-inline: contain;
}
.parameter-shelf.parameter-shelf-r5 > .parameter-shelf-options > button {
  flex: 0 0 72px;
  min-width: 72px;
  min-height: 80px;
  justify-content: flex-start;
  gap: 4px;
  padding: 7px 4px 6px;
  color: var(--muted);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 15px;
  scroll-snap-align: center;
  transition: border-color 160ms ease, background-color 160ms ease, color 160ms ease;
}
.parameter-shelf.parameter-shelf-r5 .parameter-choice-symbol {
  display: grid;
  place-items: center;
  width: 34px;
  height: 32px;
  color: var(--ink);
}
.parameter-shelf.parameter-shelf-r5 .parameter-choice-label {
  font-size: 11px;
  font-weight: 500;
  line-height: 1.35;
  max-width: 100%;
  overflow-wrap: anywhere;
}
.parameter-shelf.parameter-shelf-r5 > .parameter-shelf-options small {
  font-size: 10px;
  line-height: 1.2;
  color: inherit;
  opacity: .72;
}
.parameter-shelf.parameter-shelf-r5 > .parameter-shelf-options > button[aria-pressed='true'],
.parameter-shelf.parameter-shelf-r5 > .parameter-shelf-options > button[aria-pressed='true']:hover {
  color: var(--ink);
  border-color: color-mix(in srgb, var(--accent) 85%, var(--ink));
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 50%, transparent);
}
.parameter-shelf.parameter-shelf-r5 > .parameter-shelf-options > button:hover:not(:disabled):not([aria-pressed='true']) {
  color: var(--ink);
  background: color-mix(in srgb, var(--ink) 4%, var(--surface));
}
.parameter-shelf.parameter-shelf-r5 > .parameter-shelf-options > button:disabled {
  opacity: .38;
  cursor: not-allowed;
}
.parameter-shelf.parameter-shelf-r5 > .parameter-shelf-options > button:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 1px;
}
.parameter-shelf.parameter-shelf-r5 > .parameter-description {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 4;
  margin: 0;
}
.parameter-shelf.parameter-shelf-r5 > .parameter-description > summary {
  display: grid;
  place-items: center;
  width: 34px;
  min-height: 42px;
  padding: 0;
  margin: 0;
  list-style: none;
  border-radius: 8px;
  color: var(--muted);
}
.parameter-shelf.parameter-shelf-r5 > .parameter-description > summary::-webkit-details-marker { display: none; }
.parameter-shelf.parameter-shelf-r5 > .parameter-description > summary::after { display: none; }
.parameter-shelf.parameter-shelf-r5 > .parameter-description[open] > summary { background: var(--surface-secondary); }
.parameter-shelf.parameter-shelf-r5 > .parameter-description > .motion-disclosure {
  position: absolute;
  right: 0;
  top: 44px;
  width: min(260px, calc(100cqw - 36px));
  border-radius: 12px;
  background: var(--surface);
  box-shadow: 0 6px 24px rgb(var(--color-shadow) / 12%);
  border: 1px solid var(--line);
}
.parameter-shelf.parameter-shelf-r5 .parameter-description .motion-disclosure-content > p {
  margin: 0;
  padding: 13px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}
.advanced-inspector .color-controls-v3 > .histogram-disclosure { order: 5; }
.advanced-inspector .color-controls-v3 > .histogram-disclosure > summary { font-size: 11px; }
.advanced-inspector .advanced-inspector-scroll { gap: 10px; }
.advanced-inspector .advanced-tool-family,
.advanced-inspector .color-controls-v3 { gap: 9px; }
.advanced-inspector .tonal-tabs {
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: none;
  min-height: 38px;
}
.advanced-inspector .tonal-tabs > button { min-height: 38px; }
.advanced-inspector .portrait-manual-actions { gap: 6px; }
.advanced-inspector .portrait-manual-actions .text-button { flex: 1 1 110px; min-height: 44px; }
.advanced-inspector .portrait-ownership-note { padding: 0; border: 0; }
.advanced-inspector .portrait-category-tabs button { display: inline-flex; align-items: center; gap: 6px; }
.portrait-unavailable-tools {
  display: flex;
  flex-wrap: nowrap;
  gap: 6px;
  overflow-x: auto;
  scrollbar-width: thin;
  padding-block: 6px;
}
.portrait-unavailable-tools > button {
  display: flex;
  flex: 0 0 72px;
  align-items: center;
  flex-direction: column;
  gap: 8px;
  min-height: 76px;
  padding: 8px 4px;
  border: 0;
  border-radius: 12px;
  background: color-mix(in srgb, var(--ink) 3%, var(--surface));
  color: var(--muted);
  font-size: 11px;
  line-height: 1.4;
  opacity: .5;
}
.floating-panel[data-panel-id='inspector'] .panel-drag-header { gap: 4px; }
.floating-panel[data-panel-id='inspector'] .panel-title-drag { min-width: 0; }
.floating-panel[data-panel-id='inspector'] .panel-title-drag strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.floating-panel .panel-back-action { flex-shrink: 0; }
.studio-workspace .floating-tool-dock.tool-dock-r5 {
  max-width: min(920px, calc(100% - 32px));
  padding: 5px;
  border-radius: 15px;
  background: color-mix(in srgb, var(--surface) 96%, transparent);
  backdrop-filter: blur(8px);
}
.studio-workspace .tool-dock-r5 .dock-tool-scroll > button { min-width: 50px; min-height: 50px; }
.studio-workspace .tool-dock-r5 .dock-tool-scroll > button.active {
  color: var(--ink);
  background: transparent;
}
.studio-workspace .tool-dock-r5 .dock-selection {
  background: var(--accent-soft);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 60%, transparent);
}
.studio-workspace .context-navigation-r5.context-segment > button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 40px;
}
.advanced-history-list .history-preview-entry {
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--accent) 55%, var(--line));
  border-radius: 12px;
  background: color-mix(in srgb, var(--accent) 6%, var(--surface));
}
.history-preview-entry > strong { font-size: 12px; }
.history-preview-entry > p { margin: 6px 0; color: var(--muted); font-size: 11px; line-height: 1.5; }
.history-preview-entry .history-preview-actions { display: flex; gap: 8px; }
.history-preview-entry .history-preview-actions > button { min-height: 40px; }
@media (max-width: 759px) {
  .studio-workspace .floating-tool-dock.tool-dock-r5 { max-width: 100%; border-radius: 0; }
  .advanced-inspector .advanced-inspector-scroll { padding: 8px 12px 16px; gap: 6px; }
  .parameter-shelf.parameter-shelf-r5 { gap: 4px; }
  .parameter-shelf.parameter-shelf-r5 > .parameter-shelf-options { min-height: 84px; gap: 5px; }
  .parameter-shelf.parameter-shelf-r5 > .parameter-shelf-options > button { flex-basis: 68px; min-width: 68px; min-height: 76px; padding: 5px 3px; }
  .advanced-inspector .context-adjustment-tabs { flex-shrink: 0; min-height: 38px; }
  .advanced-inspector .context-adjustment-tabs > button { min-height: 38px; }
