import { t } from '../i18n';
import { MotionDetails } from '../motion/Presence';
import { editorControlText } from './editor-control-copy';
import { createRecipeV4, migrateRecipeToV4 } from '@ai-xiutu/editor';
import { ParameterShelf, type ShelfControl } from './ParameterShelf';
import { currentV3, type InspectorController } from './advanced-model';
import { CORNER_LABELS, preProjectiveDimensions, withProjectiveCorner } from './projective-model';

export function ProjectiveControls({ controller }: { controller: InspectorController }) {
  const { editor, apply, report } = controller,
    recipe = currentV3(editor);
  if (recipe.schemaVersion !== 4)
    return (
      <div className="advanced-tool-family">
        <p className="control-note">
          {t('四角投影使用第四代配方。升级保留已有像素语义和历史，可撤销。')}
        </p>
        <button
          className="button button-secondary"
          onClick={() => {
            try {
              apply(migrateRecipeToV4(recipe), t('升级以启用四角变换'), true);
            } catch (e) {
              report(e instanceof Error ? e.message : t('无法升级。'));
            }
          }}
        >
          {t('启用四角自由变换')}
        </button>
      </div>
    );
  const dims = editor.dimensions ?? { width: 1, height: 1 },
    frame = preProjectiveDimensions(dims, recipe);
  const neutralCorners = createRecipeV4().projective.corners;
  const controls: ShelfControl[] = CORNER_LABELS.flatMap((label, i) =>
    (['x', 'y'] as const).map((axis) => ({
      id: `projective-${i}-${axis}`,
      label: t('{corner}{axis}', { corner: t(label), axis: t(axis === 'x' ? '水平' : '垂直') }),
      value: recipe.projective.corners[i]![axis] * (axis === 'x' ? frame.width : frame.height),
      neutral: neutralCorners[i]![axis] * (axis === 'x' ? frame.width : frame.height),
      min: -2 * (axis === 'x' ? frame.width : frame.height),
      max: 3 * (axis === 'x' ? frame.width : frame.height),
      step: 0.1,
      unit: 'px',
      onChange(value) {
        const current = currentV3(editor);
        if (current.schemaVersion !== 4) return;
        try {
          apply(
            withProjectiveCorner(
              current,
              i,
              {
                ...current.projective.corners[i]!,
                [axis]: value / (axis === 'x' ? frame.width : frame.height),
              },
              dims,
              editor.pixelBudget,
            ),
            '调整' + label,
          );
        } catch (e) {
          report(e instanceof Error ? e.message : '请保持四角轮廓不交叉。');
        }
      },
    })),
  );
  return (
    <section className="advanced-tool-family" data-motion="projective-controls">
      <ParameterShelf
        controls={controls}
        label={t('四角逐点坐标')}
        onCommit={(name) => editor.commitCurrent(name)}
        onCancel={editor.cancelPreview}
      />
      <MotionDetails className="editor-help-disclosure">
        <summary>{editorControlText('快捷键')}</summary>
        <p className="control-note">
          {t(
            '拖动照片四角自由调整透视。角点支持方向键 1px、Shift 10px、Alt 0.1px；Esc 取消这一拖动。',
          )}
        </p>
      </MotionDetails>
      <div className="tonal-tabs" aria-label={t('四角变换的画幅')}>
        <button
          type="button"
          aria-pressed={recipe.projective.fit === 'contain'}
          onClick={() =>
            apply(
              { ...recipe, projective: { ...recipe.projective, fit: 'contain' } },
              t('容纳四角全部内容'),
              true,
            )
          }
        >
          {t('容纳全部')}
        </button>
        <button
          type="button"
          aria-pressed={recipe.projective.fit === 'crop'}
          onClick={() =>
            apply(
              { ...recipe, projective: { ...recipe.projective, fit: 'crop' } },
              t('保留变换前画幅'),
              true,
            )
          }
        >
          {t('保留画幅')}
        </button>
        <button
          type="button"
          aria-pressed={recipe.projective.enabled}
          onClick={() =>
            apply(
              {
                ...recipe,
                projective: { ...recipe.projective, enabled: !recipe.projective.enabled },
              },
              recipe.projective.enabled ? t('暂时关闭四角变换') : t('启用四角变换'),
              true,
            )
          }
        >
          {recipe.projective.enabled ? t('暂时关闭') : t('启用效果')}
        </button>
      </div>
      <button
        className="text-button"
        onClick={() =>
          apply({ ...recipe, projective: createRecipeV4().projective }, t('重置四角变换'), true)
        }
      >
        {t('恢复四角原位')}
      </button>
    </section>
  );
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { createElement } from 'react';
import { PORTRAIT_TOOLS } from '@ai-xiutu/portrait';
import { NUMERIC_CONTROLS } from '../src/editor/advanced-model.ts';
import {
  ParameterGlyph,
  parameterGlyphFor,
  parameterShortLabel,
  portraitParameterGlyph,
  portraitParameterDrawings,
} from '../src/editor/ParameterGlyph.tsx';
import { setLocale } from '../src/i18n/index.ts';
import { renderTestMarkup } from './support/render.ts';

test('every shipped portrait tool has its own semantic drawing, without fallback icons', () => {
  const drawings = new Set<string>();
  for (const tool of PORTRAIT_TOOLS) {
    const name = portraitParameterGlyph(tool.id);
    assert.notEqual(name, 'parameter', tool.id);
    const drawing = portraitParameterDrawings[tool.id as keyof typeof portraitParameterDrawings];
    assert.ok(drawing, tool.id);
    const signature = JSON.stringify(drawing);
    assert.equal(drawings.has(signature), false, `reused drawing for ${tool.id}`);
    drawings.add(signature);
    const markup = renderTestMarkup(createElement(ParameterGlyph, { name }));
    assert.match(markup, /viewBox="0 0 24 24"/);
    assert.match(markup, /aria-hidden="true"/);
    assert.doesNotMatch(markup, /NaN|undefined/);
  }
  assert.equal(drawings.size, Object.keys(portraitParameterDrawings).length);
});

test('all registered color, tone and geometry parameters resolve a stable functional icon', () => {
  for (const parameter of NUMERIC_CONTROLS)
    assert.notEqual(parameterGlyphFor(parameter.path), 'parameter', parameter.path);
  assert.notEqual(parameterGlyphFor('adjustments.brightness'), parameterGlyphFor('adjustments.exposure'));
  assert.notEqual(parameterGlyphFor('optics.aberrationRed'), parameterGlyphFor('optics.aberrationBlue'));
  assert.notEqual(parameterGlyphFor('effects.vignette.centerX'), parameterGlyphFor('effects.vignette.centerY'));
});

test('dynamic selection and four-corner controls retain distinct axis semantics', () => {
  const corners = Array.from({ length: 4 }, (_, index) =>
    ['x', 'y'].map((axis) => parameterGlyphFor(`projective-${index}-${axis}`)),
  ).flat();
  assert.equal(new Set(corners).size, 8);
  assert.equal(corners.includes('parameter'), false);
  for (const id of ['startx', 'starty', 'endx', 'endy', 'rotationDegrees', 'luminanceMin', 'luminanceMax'])
    assert.notEqual(parameterGlyphFor(id), 'parameter', id);
  assert.notEqual(parameterGlyphFor('startx'), parameterGlyphFor('endx'));
  assert.notEqual(parameterGlyphFor('luminanceMin'), parameterGlyphFor('levels.inputBlack'));
  assert.notEqual(parameterGlyphFor('feather'), parameterGlyphFor('adjustments.brightness'));
});

test('short parameter names are localized without changing the registry labels', async () => {
  try {
    await setLocale('en');
    assert.equal(parameterShortLabel('adjustments.whites', '白色色阶'), 'Whites');
    assert.equal(parameterShortLabel('hsl.red.hue', '红色色相'), 'Hue');
    await setLocale('zh-TW');
    assert.equal(parameterShortLabel('effects.grain.size', '颗粒间距'), '間距');
  } finally {
    await setLocale('zh-CN');
  }
});

