export type PortraitParameterName = keyof typeof portraitParameterDrawings;
export type ParameterGlyphName = keyof typeof parameterPaths | `portrait:${PortraitParameterName}`;

export function parameterShortLabel(id: string, fallback: string): string {
  if (compactLabels[id]) return editorControlText(compactLabels[id]);
  if (/^hsl\./.test(id)) {
    const labels: Record<string, EditorControlCopy> = {
      hue: '色相',
      saturation: '饱和度',
      lightness: '明度',
    };
    const key = labels[id.split('.').at(-1)!];
    return key ? editorControlText(key) : fallback;
  }
  if (/^grading\./.test(id)) {
    const labels: Record<string, EditorControlCopy> = {
      hue: '色相',
      saturation: '强度',
      luminance: '明暗',
    };
    const key = labels[id.split('.').at(-1)!];
    return key ? editorControlText(key) : fallback;
  }
  return fallback;
}
export function portraitParameterGlyph(id: string): ParameterGlyphName {
  return Object.hasOwn(portraitParameterDrawings, id)
    ? `portrait:${id as PortraitParameterName}`
    : 'parameter';
}
/** Registry paths, never translated labels, own a control's icon identity. */
export function parameterGlyphFor(id: string): ParameterGlyphName {
  const direct = pathGlyphs[id];
  if (direct) return direct;
  if (/^projective-[0-3]-[xy]$/.test(id))
    return id.replace('projective-', 'corner-') as ParameterGlyphName;
  const adjustment = id.startsWith('adjustments.') ? id.slice(12) : id;
  if (Object.hasOwn(parameterPaths, adjustment)) return adjustment as keyof typeof parameterPaths;
  if (/^hsl\.[^.]+\.(hue|saturation|lightness)$/.test(id))
    return `hsl-${id.split('.').at(-1)}` as ParameterGlyphName;
  if (/^grading\.[^.]+\.(hue|saturation|luminance)$/.test(id)) {
    const kind = id.split('.').at(-1);
    return kind === 'hue'
      ? 'grading-hue'
      : kind === 'saturation'
        ? 'grading-strength'
        : 'grading-luminance';
  }
  return 'parameter';
}

