export function panelBounds(view: Viewport, dock: Dock = 'floating', id?: PanelId) {
  const body = workspaceSize(view);
  const attached = view.bucket === 'phone' && dock === 'bottom';
  const maxWidth = Math.max(0, body.width - (attached ? 0 : PANEL_MARGIN * 2));
  const maxHeight = Math.max(
    0,
    body.height - panelBottomOffset(view) - (attached ? PANEL_MARGIN : PANEL_MARGIN * 2),
  );
  // A normal inspector needs room below its header and context navigation. Old
  // 112px preferences are migrated in place; docking, width and collapse remain.
  const inspectorMinimum =
    view.height <= 520
      ? 216
      : view.bucket === 'phone'
        ? Math.min(
            304,
            Math.max(
              224,
              Math.floor(
                canvasImageArea(view, {
                  left: 0,
                  right: 0,
                  bottom: panelBottomOffset(view) + PANEL_MARGIN,
                }).height - minimumImageArea(view).height,
              ),
            ),
          )
        : 320;
  return {
    width: body.width,
    height: body.height,
    minWidth: attached ? maxWidth : Math.min(view.bucket === 'phone' ? 224 : 240, maxWidth),
    maxWidth,
    minHeight: Math.min(
      id === 'ai'
        ? view.bucket === 'phone'
          ? 224
          : 260
        : id === 'inspector'
          ? inspectorMinimum
          : view.height <= 520
            ? 96
            : 112,
      maxHeight,
    ),
    maxHeight,
  };
}

